int prefixXorQueries_19(const vector<int>& a, int q) { int n = a.size(); vector<int> px(n + 1, 0); for (int i = 0; i < n; ++i) px[i + 1] = px[i] ^ a[i]; int total = 0; for (int i = 0; i < q; ++i) { int l = i % n, r = (i + 1) % n; if (l > r) swap(l, r); total ^= px[r + 1] ^ px[l]; } return total; }
vector<int> productExceptSelf_19(const vector<int>& a) { int n = a.size(); vector<int> res(n, 1); int p = 1; for (int i = 0; i < n; ++i) { res[i] = p; p *= a[i]; } int s = 1; for (int i = n - 1; i >= 0; --i) { res[i] *= s; s *= a[i]; } return res; }
vector<long long> sumOfSquaresPrefix_19(const vector<int>& a) { int n = a.size(); vector<long long> p(n + 1, 0); for (int i = 0; i < n; ++i) p[i + 1] = p[i] + (long long)a[i] * a[i]; return p; }
